style:
.reli-home { --reli-accent: #70b4f4; color: var(--text-color); padding: 12px 4px 28px; font-family: inherit; }
.reli-home h1 { font-size: 30px; font-weight: 650; margin: 0 0 10px; }
.reli-home h2 { font-size: 19px; font-weight: 600; margin: 14px 0; }
.reli-home p { color: var(--text-muted); line-height: 1.7; margin: 0; }
.reli-home .eyebrow { color: var(--reli-accent); letter-spacing: 2px; font-size: 11px; margin-bottom: 10px; }
.reli-home .center-grid { display: grid; grid-template-columns: repeat(4, minmax(0,1fr)); gap: 16px; margin: 26px 0 32px; }
.reli-home .center-card { border: 1px solid var(--border-color); border-radius: 13px; padding: 22px 18px 14px; background: var(--card-bg); display: flex; flex-direction: column; }
.reli-home .center-0 { border-color: var(--reli-accent); background: linear-gradient(145deg, rgba(57, 111, 190, .23), var(--card-bg)); }
.reli-home .card-top { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.reli-home .center-icon { display: inline-flex; color: var(--reli-accent); }
.reli-home .center-icon svg { width: 34px; height: 34px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
.reli-home .badge { font-size: 11px; color: var(--text-muted); border: 1px solid var(--border-color); border-radius: 20px; padding: 5px 8px; white-space: nowrap; }
.reli-home a { color: inherit; text-decoration: none; }
.reli-home a:hover { color: var(--reli-accent); }
.reli-home a:focus-visible { outline: 2px solid var(--reli-accent); outline-offset: 4px; }
.reli-home .description { min-height: 82px; font-size: 13px; }
.reli-home .center-card nav { border-top: 1px solid var(--border-color); margin-top: 16px; }
.reli-home .center-card nav a { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 11px 0; border-bottom: 1px solid var(--border-color); font-size: 13.5px; }
.reli-home .center-card nav a:last-child { border-bottom: 0; }
.reli-home .quick-section { border-top: 1px solid var(--border-color); padding-top: 14px; }
.reli-home .quick-grid { display: grid; grid-template-columns: repeat(4,minmax(0,1fr)); gap: 12px; margin-top: 18px; }
.reli-home .quick-grid a { display: flex; justify-content: space-between; gap: 8px; padding: 15px; border: 1px solid var(--border-color); border-radius: 10px; background: var(--card-bg); }
.reli-home .quick-grid span { color: var(--text-muted); }
@media(max-width: 1440px) { .reli-home .center-grid { grid-template-columns: repeat(2,minmax(0,1fr)); } }
@media(max-width: 900px) { .reli-home .center-grid { grid-template-columns: 1fr; } .reli-home .description { min-height: 0; } .reli-home .quick-grid { grid-template-columns: repeat(2,minmax(0,1fr)); } }
